Here is the commit message:
network: fix invalid memory access

This fixes a bug introduced by 959f65d32ec15cf84afe3efff1a18b0987b56c60.

Here is the root cause:
The bug was caused by an invalid memory access due to the premature freeing of network resources in the `manager_free` function before all dependent resources, such as DHCP prefixes and network links, were properly cleaned up. This could lead to dereferencing freed memory, resulting in undefined behavior or crashes.

Here is the patch:

 static Link *link_free(Link *link) {
+        Link *carrier, *master;
         Address *address;
-        Link *carrier;
         Route *route;
         Iterator i;

         assert(link);

         while ((route = set_first(link->routes)))
                 route_free(route);

         while ((route = set_first(link->routes_foreign)))
                 route_free(route);

         link->routes = set_free(link->routes);
         link->routes_foreign = set_free(link->routes_foreign);

         while ((address = set_first(link->addresses)))
                 address_free(address);

         while ((address = set_first(link->addresses_foreign)))
                 address_free(address);

         link->addresses = set_free(link->addresses);
         link->addresses_foreign = set_free(link->addresses_foreign);

         while ((address = link->pool_addresses)) {
                 LIST_REMOVE(addresses, link->pool_addresses, address);
                 address_free(address);
         }

         sd_dhcp_server_unref(link->dhcp_server);
         sd_dhcp_client_unref(link->dhcp_client);
         sd_dhcp_lease_unref(link->dhcp_lease);

         link_lldp_emit_stop(link);

         free(link->lease_file);

         sd_lldp_unref(link->lldp);
         free(link->lldp_file);

         ndisc_flush(link);

         sd_ipv4ll_unref(link->ipv4ll);
         sd_dhcp6_client_unref(link->dhcp6_client);
         sd_ndisc_unref(link->ndisc);
         sd_radv_unref(link->radv);

         link_detach_from_manager(link);

         free(link->ifname);

         free(link->kind);

         (void) unlink(link->state_file);
         free(link->state_file);

         sd_device_unref(link->sd_device);

         HASHMAP_FOREACH (carrier, link->bound_to_links, i)
                 hashmap_remove(link->bound_to_links, INT_TO_PTR(carrier->ifindex));
         hashmap_free(link->bound_to_links);

         HASHMAP_FOREACH (carrier, link->bound_by_links, i)
                 hashmap_remove(link->bound_by_links, INT_TO_PTR(carrier->ifindex));
         hashmap_free(link->bound_by_links);

         hashmap_free(link->bond_slaves);

+        if (link->network) {
+                if (link->network->bond &&
+                    link_get(link->manager, link->network->bond->ifindex, &master) >= 0)
+                        (void) hashmap_remove(master->bond_slaves, INT_TO_PTR(link->ifindex));
+        }
+
         return mfree(link);
 }



